  const step = ms < 60_000 ? 5000 : 10_000
  return `About ${formatChatcnDuration(Math.ceil(ms / step) * step, { precise: false })} left`
}

/** The time left in calm steps, shared with image generation. */
const etaLabel = generationEtaLabel

/**
 * The only shimmer in chatcn: a status label such as "Thinking". Static under reduced motion.
 * Pass `active={false}` to settle it into plain subtle text.
 */
function ShimmerText({
  active = true,
  className,
  ...props
}: React.ComponentProps<"span"> & { active?: boolean }) {
  return (
    <span
      data-slot="shimmer-text"
      className={cn("font-medium", active ? "chatcn-shimmer" : "text-(color:--chatcn-fg-subtle)", className)}
      {...props}
    />
  )
}

const iconNode14: IconNode = [
  ["path", {"d":"M3.5 15v2.5a3 3 0 0 0 3 3h11a3 3 0 0 0 3-3V15"}],
  ["path", {"d":"m7.5 10.5 3.09 3.09a2 2 0 0 0 2.82 0l3.09-3.09"}],
  ["path", {"d":"M12 3.5v7"}],
]

const DownloadIcon: Icon = /* @__PURE__ */ createIcon("download", iconNode14)

/**
 * A video job in a conversation: queue position, progress with the time left, a poster frame
 * revealed as it renders, then a player with the clip's length and resolution.
 */
export function VideoGeneration({
  prompt,
  status,
  progress,
  queuePosition,
  etaMs,
  posterSrc,
  src,
  duration,
  resolution,
  fps,
  audio,
  aspectRatio = "16:9",
  settings,
  statusText,
  errorText,
  blockedText,
  onRetry,
  onCancel,
  onEditPrompt,
  onDownload,
  filename,
  actions,
  autoPlay,
  loop,
  className,
  ...props
}: VideoGenerationProps) {
  const ratio = parseAspectRatio(aspectRatio)
  const generating = status === "generating"
  const eta = useChatcnMediaEta(progress, { active: generating, etaMs })
  const [instant] = React.useState(() => status === "done")
  const percent = progress === undefined ? undefined : Math.round(Math.min(100, progress))
  const label = statusText ?? videoStage(progress)
  const done = status === "done" && Boolean(src)

  const facts = [
    typeof aspectRatio === "string" ? aspectRatio : null,
    duration !== undefined ? formatChatcnDuration(duration * 1000, { precise: false }) : null,
    resolutionLabel(resolution),
    fps ? `${fps} fps` : null,
    audio === undefined ? null : audio ? "Sound" : "No sound",
    ...(settings ?? []),
  ].filter((item) => item !== null && item !== undefined && item !== false)

  return (
    <div
      data-slot="video-generation"
      data-generation-state={status}
      aria-busy={status === "queued" || generating || undefined}
      className={cn("text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex w-full min-w-0 flex-col gap-3", className)}
      {...props}
    >
      <div data-slot="video-generation-header" className="flex items-start gap-2">
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) line-clamp-3 text-pretty">{prompt}</p>
          {facts.length > 0 ? (
            <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex flex-wrap items-center gap-x-1.5 tabular-nums">
              {facts.map((item, i) => (
                <React.Fragment key={i}>
                  {i > 0 ? <span aria-hidden="true">·</span> : null}
                  <span>{item}</span>
                </React.Fragment>
              ))}
            </p>
          ) : null}
        </div>
        <CopyButton
          value={prompt}
          label="Copy prompt"
          size="icon-sm"
          className="-me-1 pointer-coarse:size-11"
        />
      </div>

      <div className="rounded-(--chatcn-radius-lg) relative">
        {done && src ? (
          <VideoPlayer
            src={src}
            poster={posterSrc}
            title={prompt}
            duration={duration}
            aspectRatio={ratio}
            autoPlay={autoPlay}
            // Browsers only autoplay muted video; the viewer can unmute from the bar.
            defaultMuted={autoPlay}
            loop={loop}
            className="rounded-(--chatcn-radius-lg)"
          />
        ) : (
          <GenerationFrame
            image={posterSrc ? { src: posterSrc } : undefined}
            phase={status === "done" ? "generating" : status}
            progress={status === "done" ? 100 : progress}
            ratio={ratio}
            instant={instant}
            alt=""
            className="rounded-(--chatcn-radius-lg)"
          />
        )}

        {status === "failed" ? (
          <GenerationNotice
            tone="error"
            icon={<CircleXIcon />}
            title="Video generation failed"
            actions={
              onRetry ? (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={onRetry}
                  className="pointer-coarse:h-11"
                >
                  <RotateCcwIcon />
                  Retry generation
                </Button>
              ) : null
            }
          >
            {errorText ?? "Rendering stopped before the clip finished. Try again in a moment."}
          </GenerationNotice>
        ) : status === "blocked" ? (
          <GenerationNotice
            icon={<ShieldIcon />}
            title="This video wasn’t created"
            actions={
              onEditPrompt ? (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={onEditPrompt}
                  className="pointer-coarse:h-11"
                >
                  Edit prompt
                </Button>
              ) : null
            }
          >
            {blockedText ??
              "The prompt may go against the content policy. Try describing the action and setting instead of a specific person."}
          </GenerationNotice>
        ) : null}
      </div>

      {status === "failed" || status === "blocked" ? null : (
        <div data-slot="video-generation-footer" className="flex h-8 min-w-0 items-center gap-2">
          {status === "queued" ? (
            <div className="text-[0.8125rem]/[1.25rem] flex min-w-0 flex-1 items-center gap-2">
              <ClockIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-3.5 shrink-0" />
              <span className="text-(color:--chatcn-fg-muted) shrink-0 font-medium">Queued</span>
              {queuePosition ? (
                <span className="text-(color:--chatcn-fg-subtle) shrink-0 whitespace-nowrap tabular-nums">
                  Position {queuePosition}
                </span>
              ) : null}
              {etaMs !== undefined ? (
                <>
                  <span aria-hidden="true" className="text-(color:--chatcn-fg-subtle)">
                    ·
                  </span>
                  <span className="text-(color:--chatcn-fg-subtle) truncate tabular-nums">
                    About {formatChatcnDuration(etaMs, { precise: false })} wait
                  </span>
                </>
              ) : null}
            </div>
          ) : generating || !done ? (
            <div
              role="progressbar"
              aria-label={label}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={percent}
              aria-valuetext={[
                percent !== undefined ? `${percent}%` : null,
                etaLabel(eta, progress),
              ]
                .filter(Boolean)
                .join(", ")}
              className="text-[0.8125rem]/[1.25rem] flex min-w-0 flex-1 items-center gap-2"
            >
              <ShimmerText className="truncate">{label}</ShimmerText>
              {percent !== undefined ? (
                <span className="text-(color:--chatcn-fg-subtle) tabular-nums">{percent}%</span>
              ) : null}
              {etaLabel(eta, progress) ? (
                <>
                  <span aria-hidden="true" className="text-(color:--chatcn-fg-subtle)">
                    ·
                  </span>
                  <span className="text-(color:--chatcn-fg-subtle) truncate tabular-nums">
                    {etaLabel(eta, progress)}
                  </span>
                </>
              ) : null}
            </div>
          ) : (
            <div className="chatcn-scroll -ms-2.5 flex min-w-0 flex-1 items-center gap-0.5 overflow-x-auto">
              {actions}
            </div>
          )}

          {status === "queued" || generating ? (
            onCancel ? (
              <Button size="sm" onClick={onCancel} className="-me-2.5 pointer-coarse:h-11">
                Cancel
              </Button>
            ) : null
          ) : done && src ? (
            <Tooltip content="Download">
              {onDownload ? (
                <Button
                  size="icon-sm"
                  aria-label="Download video"
                  onClick={onDownload}
                  className="-me-1.5 pointer-coarse:size-11"
                >
                  <DownloadIcon />
                </Button>
              ) : (
                <a
                  href={src}
                  download={filename ?? "video"}
                  aria-label="Download video"
                  className={cn(
                    buttonVariants({ variant: "ghost", size: "icon-sm" }),
                    "-me-1.5 pointer-coarse:size-11",
                  )}
                >
                  <DownloadIcon />
                </a>
              )}
            </Tooltip>
          ) : null}
        </div>
      )}

      <span aria-live="polite" className="sr-only">
        {status === "queued"
          ? queuePosition
            ? `Video queued, position ${queuePosition}`
            : "Video queued"
          : status === "generating"
            ? "Generating video"
            : status === "done"
              ? "Video ready"
              : status === "failed"
                ? "Video generation failed"
                : "The video was not created"}
      </span>
    </div>
  )
}

export default VideoGeneration

